steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        issues(first: 20, filter: {
          label: {name: {eq: \"Customer Tier\"}},
          assignee: {name: {contains: \"Priya Nair\"}},
          team: {name: {eq: \"Support\"}}
        }) {
          nodes {
            id
            identifier
            title
            priority
            assignee { name }
            labels { name }
            team { name }
          }
        }
      }
    "
  }'
